{
  "skill": "running-ceridwen-experiments"
}

{
  "command": "cd \"$PWD\"; ls results/ | tail -40; grep -ril \"ten-galaxy\\|test set\\|ten galaxies\\|10 galaxies\" wiki/research wiki/notes scripts .agents 2>/dev/null | head -20",
  "description": "List results and find ten-galaxy test set"
}

{
  "command": "ls -R results/quiescent-test-set | head -30; ls results/quiescent-test-set-speedups-2026-10-01 results/dr2-quiescent-new-defaults; cat results/quiescent-test-set-speedups-2026-10-01/experiment.json 2>/dev/null; cat results/dr2-quiescent-new-defaults/experiment.json 2>/dev/null; sed -n 1,40p scripts/select_quiescent_test_set.py",
  "description": "Inspect existing test-set configs"
}

{
  "command": "cat results/quiescent-test-set/experiment.json results/quiescent-test-set/targets.json; ls results/quiescent-test-set-speedups-2026-10-01/run; cat results/quiescent-test-set-speedups-2026-10-01/run/experiment.json 2>/dev/null | head -60; git log --oneline -3 -- results/quiescent-test-set",
  "description": "Read test-set config and targets"
}

{
  "command": "ls -la results/absorption-mask; cat results/absorption-mask/*.json 2>/dev/null | head -80; git log --oneline main..HEAD | head; git log --oneline HEAD..main | head",
  "description": "Inspect absorption-mask result dir and branch"
}

{
  "command": "python3 -c \"import json;m=json.load(open('results/quiescent-test-set-speedups-2026-10-01/run/manifest.json'));print(list(m.keys()));print(json.dumps(m.get('config',m.get('experiment')),indent=1)[:1500])\"; python3 scripts/experiment.py run --help 2>&1 | head -40; ls results/*/experiment.json",
  "description": "Check runner options and prior config format"
}

{
  "command": "cat results/m1-210210-nebular-2026-09-30/experiment.json results/speedup-free-2026-09-30/experiment.json; ls results/speedup-free-2026-09-30",
  "description": "View example experiment configs"
}

{
  "targets": [
    "M1_210210"
  ],
  "seed": 20260927,
  "settings": {
    "ssp_grid": "~/.ceridwen/grids/amist_c3k_hr_krou_afe_nebular.h5"
  },
  "priors": {
    "diffuse_delta": "Uniform(low=-3.0, high=0.4)",
    "diffuse_Ebump": "Uniform(low=0.0, high=12.0)"
  },
  "arms": {
    "neb": {
      "settings": {
        "emission_lines": [3726.0, 3728.8, 4958.9, 5006.8]
      }
    },
    "neb_eline": {
      "settings": {
        "emission_line_marginalisation": true
      }
    },
    "neb_maskca": {
      "settings": {
        "emission_lines": [3726.0, 3728.8, 3934.77, 3969.59, 4958.9, 5006.8]
      }
    }
  }
}
{
  "targets": ["M1_210210"],
  "seed": 20260930,
  "settings": {},
  "priors": {},
  "arms": {"fit": {}}
}
driver.log
experiment.json
free_arm.py
free_compare.py
gpu_free.py
run

{
  "command": "D=results/quiescent-test-set-defaults-2026-10-12; python3 scripts/experiment.py run $D/experiment.json --gpu \"RTX 5090\" --output $D/run --dry-run > $TMPDIR/dry.json 2>&1; echo exit=$?; head -60 $TMPDIR/dry.json; grep -niE \"warn|error|missing|estimat\" $TMPDIR/dry.json | head; ls $D",
  "description": "Check dry-run head, warnings and exit status"
}

{
  "command": "git add results/quiescent-test-set-defaults-2026-10-12/experiment.json && git commit -q -m \"Config: production defaults on the 10-galaxy quiescent test set\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\" && git log --oneline -1 && git push 2>&1 | tail -3",
  "description": "Commit config and push branch"
}

{
  "command": "bd create \"Default-settings fit of 10-galaxy quiescent test set\" -t task -d \"Config results/quiescent-test-set-defaults-2026-10-12/experiment.json; dry run passed (commit 7354c90 source, RTX 5090, \\$1 cap). GPU run not launched, awaiting go-ahead.\" 2>&1 | tail -2",
  "description": "Record a short Beads status"
}
